import { createRoot } from 'react-dom/client';
import { App } from './App';
import { PreferencesApp } from './PreferencesApp';
import { OrcaImportApp } from './OrcaImportApp';
import { GuideApp } from './GuideApp';
import { nativeTransport } from './bridge/client';
import { installDropGuard } from './bridge/dropGuard';
import { applyAppearance, applyStaticTokens } from './tokens';
import './styles.css';

applyStaticTokens();
applyAppearance('light');
installDropGuard(window);

const query = new URLSearchParams(window.location.search);
// The temporary printer task chat loads the same page with ?panel=printer: the same
// thread and composer, with the printer session's card pinned above them
// instead of the project's setup card. See App.tsx.
const panel = query.get('panel') === 'printer';
// JusPrin's Preferences window loads it with ?panel=preferences: its own
// surface, drawn with the same Agent connection rows. See PreferencesApp.tsx.
const preferences = query.get('panel') === 'preferences';
// Printer › Import printers from OrcaSlicer…'s and Import printers from JusPrin 1…'s window loads it with
// ?panel=orca-import. See OrcaImportApp.tsx.
const orcaImport = query.get('panel') === 'orca-import';
// Help › JusPrin guide…'s window loads it with ?panel=guide. See GuideApp.tsx.
const guide = query.get('panel') === 'guide';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    {preferences
      ? <PreferencesApp getTransport={nativeTransport} />
      : orcaImport
        ? <OrcaImportApp getTransport={nativeTransport} />
        : guide
          ? <GuideApp getTransport={nativeTransport} />
          : <App getTransport={nativeTransport} printerPanel={panel} />}
  </StrictMode>,
);
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { nativeTransport } from './bridge/client';
import { applyAppearance, applyStaticTokens } from './tokens';
import './styles.css';

applyStaticTokens();
applyAppearance('light');

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App getTransport={nativeTransport} />
  </StrictMode>,
);
import '@testing-library/jest-dom/vitest';

// jsdom lays nothing out, so it has neither of these; the page uses them only
// to re-measure the composer and to keep a highlighted menu row in view.
globalThis.ResizeObserver ??= class { observe() {} unobserve() {} disconnect() {} };
Element.prototype.scrollIntoView ??= function () {};
import '@testing-library/jest-dom/vitest';

// jsdom lays nothing out, so it has no scrolling; the Print history brings the
// entry a chat marker named into view.
Element.prototype.scrollIntoView ??= function () {};
import { defineConfig } from 'vitest/config';
import { searchForWorkspaceRoot } from 'vite';
import react from '@vitejs/plugin-react';
import { viteSingleFile } from 'vite-plugin-singlefile';
import { fileURLToPath } from 'node:url';

const resources = fileURLToPath(new URL('../../../../../resources', import.meta.url));
const shared = fileURLToPath(new URL('../WebShared', import.meta.url));

// The bundle must be a single self-contained file: WKWebView does not load
// file: subresources reliably (POC lesson), so everything inlines into one
// index.html packaged at resources/jusprin/home/index.html.
export default defineConfig({
  plugins: [react(), viteSingleFile()],
  resolve: {
    // The first launch draws the Agent page's add-printer form, whose files
    // would otherwise find the Agent page's own copy of React.
    dedupe: ['react', 'react-dom'],
    alias: {
      '@resources': resources,
      '@shared': shared,
    },
  },
  server: {
    port: 5174,
    strictPort: true,
    // The CSS loads icons from resources/ and fonts from WebShared/, both outside
    // this folder, which the dev server refuses (403) unless they are allowed.
    fs: { allow: [searchForWorkspaceRoot(process.cwd()), resources, shared] },
  },
{
  "compilerOptions": {
    "target": "ES2022",
    "lib": ["ES2022", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "moduleResolution": "bundler",
    "jsx": "react-jsx",
    "strict": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "resolveJsonModule": true,
    "isolatedModules": true,
    "skipLibCheck": true,
    "noEmit": true,
    "types": ["vite/client", "vitest/globals", "@testing-library/jest-dom"],
    "paths": {
      "@resources/*": ["../../../../../resources/*"],
      "@shared/*": ["../WebShared/*"]
    }
  },
  "include": ["src", "vite.config.ts"]
}

